[CmdletBinding()]
param([string]$ManifestPath=(Join-Path $PSScriptRoot '..\references\route.manifest.json'))
$ErrorActionPreference='Stop'; $manifestFull=(Resolve-Path -LiteralPath $ManifestPath).Path; $m=Get-Content -LiteralPath $manifestFull -Encoding UTF8 -Raw | ConvertFrom-Json; $e=@(); $parserProperties=@($m.parsers.PSObject.Properties); if($m.schemaVersion -ne 1){$e+='schemaVersion must be 1'}; if($m.maxReferenceDepth -gt 3){$e+='maxReferenceDepth exceeds 3'}; if($m.maxReads -gt 256){$e+='maxReads exceeds 256'}; if($m.failurePolicy -ne 'fail-closed'){$e+='failurePolicy must be fail-closed'}; if($parserProperties.Count -eq 0){$e+='no parsers registered'}; $ids=@{}; foreach($p in $parserProperties){$route=$p.Value; if([string]::IsNullOrWhiteSpace($route.parserId)){$e+="parser $($p.Name) missing parserId"} elseif($ids.ContainsKey($route.parserId)){$e+="duplicate parserId $($route.parserId)"}else{$ids[$route.parserId]=$true}; $contractPath=Join-Path (Split-Path $manifestFull -Parent) $route.contract; if(-not (Test-Path -LiteralPath $contractPath -PathType Leaf)){$e+="parser $($p.Name) contract missing: $($route.contract)"} }; $r=[ordered]@{validator='Test-ESReaderRouteManifest';valid=($e.Count -eq 0);errorCount=$e.Count;parserCount=$parserProperties.Count;errors=$e}; $r|ConvertTo-Json -Depth 8; if($e.Count){exit 1}else{exit 0}
